function mkText(parent, chars, x, y, w, size, weight, color, lh) {
  const t = figma.createText();
  t.fontName = {family: weight.startsWith('Q')?'Quicksand':'Nunito', style: weight.endsWith('Bold')&&!weight.endsWith('SemiBold')?'Bold':(weight.endsWith('SemiBold')?'SemiBold':'Regular')};
  t.characters = chars;
  t.fontSize = size;
  t.x = x; t.y = y;
  t.resize(w, t.height);
  t.fills = [{type:'SOLID', color: color}];
  if (lh) t.lineHeight = {value: lh, unit:'PIXELS'};
  parent.appendChild(t);
  return t;
}

