function entryCard(time, title, tag, note, yy){
  const card = figma.createFrame();
  card.name = 'JournalEntry';
  card.layoutMode = 'NONE';
  card.resize(342, tag ? 112 : 92);
  card.x = 24; card.y = yy;
  card.cornerRadius = 14;
  card.fills = [{type:'SOLID', color:{r:1,g:1,b:1}}];
  card.effects = [{type:'DROP_SHADOW', color:{r:0,g:0,b:0,a:0.05}, offset:{x:0,y:1}, radius:6, visible:true, blendMode:'NORMAL'}];
  frame.appendChild(card);

  const timeT = figma.createText();
  timeT.fontName = {family:'Nunito', style:'SemiBold'};
  timeT.characters = time;
  timeT.fontSize = 12;
  timeT.x = 16; timeT.y = 14;
  timeT.fills = [{type:'SOLID', color:{r:0.533,g:0.812,b:0.651}}];
  card.appendChild(timeT);

  const titleT = figma.createText();
  titleT.fontName = {family:'Quicksand', style:'Bold'};
  titleT.characters = title;
  titleT.fontSize = 15;
  titleT.x = 16; titleT.y = 32;
  titleT.fills = [{type:'SOLID', color:{r:0.12,g:0.15,b:0.14}}];
  card.appendChild(titleT);

  let tagBottom = 32 + titleT.height;
  if (tag){
    const tagChip = figma.createFrame();
    tagChip.layoutMode='NONE';
    tagChip.cornerRadius = 8;
    tagChip.fills=[{type:'SOLID', color:{r:0.961,g:0.902,b:0.812}}];
    const tagT = figma.createText();
    tagT.fontName = {family:'Nunito', style:'SemiBold'};
    tagT.characters = tag;
    tagT.fontSize = 11;
    tagT.fills=[{type:'SOLID', color:{r:0.69,g:0.48,b:0.16}}];
    tagChip.appendChild(tagT);
    tagT.x = 8; tagT.y = 3;
    tagChip.resize(tagT.width+16, tagT.height+6);
    tagChip.x = 16 + titleT.width + 8; tagChip.y = 32 + (titleT.height-tagChip.height)/2;
    card.appendChild(tagChip);
  }

  const noteT = figma.createText();
  noteT.fontName = {family:'Nunito', style:'Regular'};
  noteT.characters = note;
  noteT.fontSize = 13;
  noteT.x = 16; noteT.y = 32+titleT.height+8;
  noteT.resize(310, noteT.height);
  noteT.fills = [{type:'SOLID', color:{r:0.42,g:0.47,b:0.45}}];
  card.appendChild(noteT);

  card.resize(342, Math.max(92, noteT.y + noteT.height + 14));
  return card;
}

