function mkChip(label, selected, iconId){
  const src = selected? chipSelected : chipDefault;
  const inst = src.createInstance();
  const det = inst.detachInstance();
  det.layoutMode='HORIZONTAL';
  det.primaryAxisSizingMode='AUTO';
  det.counterAxisAlignItems='CENTER';
  det.itemSpacing=6;
  det.paddingLeft=16; det.paddingRight=16; det.paddingTop=10; det.paddingBottom=10;
  const txt = det.findOne(n=>n.type==='TEXT');
  txt.characters = label;
  if(iconId){
    const iconComp = figma.getNodeById(iconId);
    const icon = iconComp.createInstance();
    icon.resize(16,16);
    det.insertChild(0, icon);
  }
  return det;
}
