async function wireTabBar(frame, tabBarName, map){
  const tb = frame.findOne(n=>n.name===tabBarName);
  if(!tb) return 'MISSING:'+tabBarName;
  const results=[];
  for(const [label, destKey] of Object.entries(map)){
    if(!destKey) continue;
    const destId = ids[destKey];
    const node = tb.findOne(n=>n.name===label);
    if(node){ await node.setReactionsAsync(mkNav(destId)); results.push(label+'->'+destKey); }
    else results.push('MISSING_NODE:'+label);
  }
  return results;
}

